/* VLOnto - downloads page (static tables generated by scripts/site/build_site.py downloads_html): copy buttons, the ready
   flag and the language mode (docs/i18n.md). js/i18n.js applies the data-i18n texts; this script writes the sentences
   with links and numbers, the file and table descriptions (dl.desc.*, dl.kg.*) and every number and size in the mode's
   format (40,816 and 77.2 MB in EN and EN–VI, 40.816 and 77,2 MB in VI), and rewrites them in place on 'vl:lang'. */
(function () {
  'use strict';
  var VL = window.VL, M = window.__VLONTO_METRICS;
  VL.chrome();
  M.page = 'downloads';
  var esc = VL.esc;
  document.addEventListener('click', function (e) {
    var b = e.target.closest('.copy-hash');
    if (b) VL.copy(b.getAttribute('data-hash'));
  });

  /* build_site.human() with the mode's grouping and decimal mark: B, then KB / MB / GB with one decimal, rounded half to
     even like Python's format (x * 10 is exact for sizes below 2^49 bytes, so a tie is a real tie) */
  function human(n) {
    var units = ['B', 'KB', 'MB', 'GB'], i = 0, x = n;
    while (x >= 1024 && i < 3) { x /= 1024; i++; }
    if (!i) return VL.fmt(n) + ' B';
    var r = x * 10, f = Math.floor(r), d = r - f, q = d > 0.5 || (d === 0.5 && f % 2) ? f + 1 : f;
    return VL.fmt(Math.floor(q / 10)) + VL.fmt(0.5).charAt(1) + (q % 10) + ' ' + units[i];
  }
  /* "four" / "bốn" for small counts in running text, else the number */
  function word(n) { return VL.i18n.has('dl.word.' + n) ? VL.U('dl.word.' + n) : VL.fmt(n); }
  function langAttr(l) { return l && l !== VL.i18n.htmlLang() ? ' lang="' + l + '"' : ''; }
  var GROUPED = /\b\d{1,3}(?:,\d{3})+\b/;
  /* the Vietnamese words of an English text (glosses such as "Articles (Điều)") marked lang="vi" outside VI; h = escaped text */
  var VI_WORD = /[A-Za-zÀ-ỹĐđ]*[àáạảãâầấậẩẫăằắặẳẵèéẹẻẽêềếệểễìíịỉĩòóọỏõôồốộổỗơờớợởỡùúụủũưừứựửữỳýỵỷỹđĐ][A-Za-zÀ-ỹĐđ]*/g;
  function markVi(h) { return VL.lang() === 'vi' ? h : h.replace(VI_WORD, function (w) { return '<span lang="vi">' + w + '</span>'; }); }
  /* a description from the dictionary while the dictionary's English is the markup's text (numbers aside); otherwise the
     markup's English stays (marked lang="en") and the row is counted in M.downloadsDescFallback */
  var fallback = 0;
  function describe(el, key, html) {
    if (el.__en == null) el.__en = el.textContent;
    var e = VL.i18n.get(key), n = el.getAttribute('data-n');
    el.setAttribute('data-vl-text', 'ok');
    if (e && e.en.replace('{n}', '#') === el.__en.replace(GROUPED, '#')) {
      el.innerHTML = markVi(html(n ? { n: VL.fmt(+n) } : null));
      return;
    }
    fallback++;
    el.innerHTML = '<span' + langAttr('en') + '>' + esc(el.__en) + '</span>';
  }
  /* the hrefs of the sentences' links, as the build wrote them */
  function href(sel, i, fb) { var a = VL.$$(sel + ' a')[i || 0]; return a ? a.getAttribute('href') : fb; }
  var LINKS = {
    sums: href('#dl-lead', 0, 'downloads/SHA256SUMS.txt'), lic: href('#dl-vendor-text', 0, 'vendor/THIRD_PARTY_LICENSES.md'),
    ofl1: href('#dl-vendor-text', 1, 'fonts/OFL-Libertinus.txt'), ofl2: href('#dl-vendor-text', 2, 'fonts/OFL-BeVietnamPro.txt'),
    repo: href('#dl-full-text', 0, 'https://github.com/tmquan/VLOnto')
  };

  function render() {
    var lead = VL.$('#dl-lead');
    if (lead) {
      lead.innerHTML = VL.UH('dl.lead', { n: VL.fmt(+lead.getAttribute('data-n')), size: human(+lead.getAttribute('data-bytes')) },
        { html: { sums: '<a href="' + esc(LINKS.sums) + '">SHA256SUMS.txt</a>', cmd: '<code>sha256sum -c</code>' } });
    }
    var t = VL.$('#dl-data-text');
    if (t) t.innerHTML = VL.UH('dl.data.text', null, { html: { code: '<code>window.VLONTO</code>', file: '<code>file://</code>' } });
    t = VL.$('#dl-vendor-text');
    if (t) {
      t.innerHTML = VL.UH('dl.vendor.text', null, { html: { lic: '<a href="' + esc(LINKS.lic) + '">' + esc(VL.U('dl.vendor.licences')) + '</a>',
        ofl1: '<a href="' + esc(LINKS.ofl1) + '">OFL</a>', ofl2: '<a href="' + esc(LINKS.ofl2) + '">OFL</a>', dir: '<code>fonts/embedded/</code>' } });
    }
    t = VL.$('#dl-full-text');
    if (t) {
      t.innerHTML = VL.UH('dl.full.text', { n: word(+t.getAttribute('data-n')) },
        { html: { repo: '<a href="' + esc(LINKS.repo) + '" target="_blank" rel="noopener">' + esc(VL.U('dl.full.repo')) + '</a>' } });
    }
    t = VL.$('#dl-full-tables');
    if (t) {
      t.innerHTML = VL.UH('dl.full.tables', { n: VL.fmt(+t.getAttribute('data-n')) },
        { html: { release: '<span data-vl-release>' + esc(VL.releaseLabel()) + '</span>' } });
    }
    ['dl-lead', 'dl-data-text', 'dl-vendor-text', 'dl-full-text', 'dl-full-tables'].forEach(function (id) {
      var el = document.getElementById(id);
      if (el) el.setAttribute('data-vl-text', 'ok');
    });
    fallback = 0;
    VL.$$('td[data-desc]').forEach(function (el) {
      var s = el.getAttribute('data-desc');
      describe(el, 'dl.desc.' + s, function (v) { return VL.UH('dl.desc.' + s, v); });
    });
    VL.$$('td[data-kg]').forEach(function (el) {
      var s = el.getAttribute('data-kg');
      describe(el, 'dl.kg.' + s, function (v) { return VL.UH('dl.kg.' + s, v); });
    });
    VL.$$('td.num[data-n]').forEach(function (el) { el.textContent = VL.fmt(+el.getAttribute('data-n')); });
    VL.$$('td[data-bytes]').forEach(function (el) { el.textContent = human(+el.getAttribute('data-bytes')); });
    VL.$$('td[data-triples]').forEach(function (el) { el.innerHTML = VL.UH('dl.full.triples', { n: VL.fmt(+el.getAttribute('data-triples')) }); });
    M.downloadsDescFallback = fallback;
    M.downloadsLang = VL.lang();
  }
  render();
  document.addEventListener('vl:lang', function () { render(); M.downloadsLangRenders = (M.downloadsLangRenders || 0) + 1; });
  M.downloadRows = VL.$$('table.files tbody tr').length;
  VL.fontsReady().then(function () { VL.setReady(); });
})();
